SELECT c.*, u.name AS assign_name FROM clue AS c
LEFT JOIN user AS u ON c.user_id = u.id


        AND c.id = #{clueDTO.clueId}


        AND c.name LIKE CONCAT('%', #{clueDTO.name}, '%')


        AND c.phone LIKE CONCAT('%', #{clueDTO.phone}, '%')


        AND c.status = #{clueDTO.status}


        AND c.channel = #{clueDTO.channel}


        AND c.activity_id = #{clueDTO.activityId}


        AND c.user_id = #{clueDTO.userId}


        AND u.name LIKE CONCAT('%', #{clueDTO.assignName}, '%')


        AND c.subject = #{clueDTO.subject}


        AND c.level = #{clueDTO.level}


ORDER BY c.id DESC

SELECT c.*, a.name AS activity_name FROM clue AS c LEFT JOIN activity AS a ON c.activity_id = a.id
AND c.status = 1
AND c.id = #{clueDTO.clueId}
AND c.phone LIKE CONCAT('%', #{clueDTO.phone}, '%')
AND c.channel = #{clueDTO.channel}
ORDER BY c.id DESC

SELECT c.*, u.name AS assign_name FROM clue AS c
LEFT JOIN user AS u ON c.user_id = u.id
WHERE c.id = #{id}
